mapper.select:
SELECT t.tenant_code AS tenant_code, t.status AS status, t.isolation_mode AS isolation_mode, t.schema_name AS schema_name, t.db_version AS db_version, t.upgraded_at AS upgraded_at, t.expire_time AS expire_time, t.create_time AS create_time, e.company_name AS company_name, e.industry AS industry, COALESCE(q.qps_limit, 0) AS qps_limit, COALESCE(q.daily_request_limit, 0) AS daily_request_limit, COALESCE(q.enabled, FALSE) AS quota_enabled, COALESCE(u.request_count, 0) AS today_requests, COALESCE(u.rejected_count, 0) AS today_rejected, (SELECT COUNT(1) FROM tenant_schema_upgrade s WHERE s.tenant_code = t.tenant_code) AS upgrade_count, (SELECT MAX(s.started_at) FROM tenant_schema_upgrade s WHERE s.tenant_code = t.tenant_code AND s.status = 2) AS last_upgrade_at, (SELECT COUNT(1) FROM tenant_security_event v WHERE v.tenant_code = t.tenant_code AND v.event_time >= CURRENT_DATE) AS today_security_events FROM tenant t LEFT JOIN enterprise e ON e.id = t.enterprise_id AND e.is_deleted = FALSE LEFT JOIN tenant_quota q ON q.tenant_code = t.tenant_code AND q.is_deleted = FALSE LEFT JOIN tenant_usage_daily u ON u.tenant_code = t.tenant_code AND u.stat_date = CURRENT_DATE WHERE t.is_deleted = FALSE
AND t.status = #{status}
AND t.isolation_mode = #{isolationMode}
AND (e.company_name ILIKE '%' || #{keyword} || '%' OR t.tenant_code ILIKE '%' || #{keyword} || '%')
ORDER BY t.create_time DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM tenant t LEFT JOIN enterprise e ON e.id = t.enterprise_id AND e.is_deleted = FALSE WHERE t.is_deleted = FALSE
AND t.status = #{status}
AND t.isolation_mode = #{isolationMode}
AND (e.company_name ILIKE '%' || #{keyword} || '%' OR t.tenant_code ILIKE '%' || #{keyword} || '%')

SELECT v.id, v.tenant_code, v.event_type, v.detail, v.request_uri, v.request_method, v.client_ip, v.token_tenant, v.operator_name, v.event_time FROM tenant_security_event v WHERE 1 = 1
AND v.tenant_code = #{tenantCode}
ORDER BY v.event_time DESC, v.id DESC LIMIT #{limit}
